svg.script:
(function () {
  'use strict';

  // ── Data ──────────────────────────────────────────────
  var VALUES = [5, 3, 8, 1, 6, 4];
  var N = VALUES.length;

  // ── Colors ────────────────────────────────────────────
  var C_NORMAL  = '#388bfd';
  var C_COMPARE = '#d29922';
  var C_SWAP    = '#f85149';
  var C_SORTED  = '#3fb950';
  var NS = 'http://www.w3.org/2000/svg';

  // ── Layout ────────────────────────────────────────────
  var BASE_Y  = 435;
  var BAR_W   = 68;
  var BAR_GAP = 10;
  var BAR_X0  = 62;
  var MAX_H   = 260;
  var MAX_VAL = 8;

  function barX(i) { return BAR_X0 + i * (BAR_W + BAR_GAP); }
  function barH(v) { return Math.round(v / MAX_VAL * MAX_H); }

  // ── Timing (ms at 1× speed) ───────────────────────────
  var D_INIT    = 800;
  var D_PASS_ST = 600;
  var D_INNER   = 400;
  var D_COMPARE = 750;
  var D_SWAP    = 950;
  var D_PASS_EN = 700;
  var D_DONE    = 2800;

  // codeLine keys: 'N1'=function header, '1'=pass loop,
  //                '2'=inner loop, '3'=if, '4'=swap, '5'=return
  function computeSteps(arr0) {
    var arr = arr0.slice();
    var steps = [];
    var cmp = 0, swp = 0;
    var n = arr.length;

    steps.push({
      arr: arr.slice(), lo:-1, hi:-1, sortedFrom:n,
      swapping:false, pass:0, cmp:cmp, swp:swp,
      delay:D_INIT, codeLine:'N1',
      msg:'Initial array \u2014 ready to sort',
      sub:''
    });

    for (var pass = 0; pass < n - 1; pass++) {
      var sortedFrom = n - pass;

      steps.push({
        arr: arr.slice(), lo:-1, hi:-1, sortedFrom:sortedFrom,
        swapping:false, pass:pass+1, cmp:cmp, swp:swp,
        delay:D_PASS_ST, codeLine:'1',
        msg:'Starting Pass ' + (pass+1) + ' of ' + (n-1),
        sub:'Largest unsorted element will bubble to position ' + (sortedFrom-1)
      });

      for (var i = 0; i < sortedFrom - 1; i++) {
        steps.push({
          arr: arr.slice(), lo:i, hi:i+1, sortedFrom:sortedFrom,
          swapping:false, pass:pass+1, cmp:cmp, swp:swp,
          delay:D_INNER, codeLine:'2',
          msg:'Checking indices [' + i + '] and [' + (i+1) + ']',
          sub:'arr[' + i + '] = ' + arr[i] + ',  arr[' + (i+1) + '] = ' + arr[i+1]
        });

        cmp++;
        var willSwap = arr[i] > arr[i+1];

        steps.push({
          arr: arr.slice(), lo:i, hi:i+1, sortedFrom:sortedFrom,
          swapping:false, pass:pass+1, cmp:cmp, swp:swp,
          delay:D_COMPARE, codeLine:'3',
          msg:'Compare arr[' + i + ']=' + arr[i] + ' vs arr[' + (i+1) + ']=' + arr[i+1],
          sub:willSwap
            ? arr[i] + ' > ' + arr[i+1] + ' \u2192 out of order, swap needed'
            : arr[i] + ' \u2264 ' + arr[i+1] + ' \u2192 already in order, skip'
        });

        if (willSwap) {
          var tmp = arr[i]; arr[i] = arr[i+1]; arr[i+1] = tmp;
          swp++;
          steps.push({
            arr: arr.slice(), lo:i, hi:i+1, sortedFrom:sortedFrom,
            swapping:true, pass:pass+1, cmp:cmp, swp:swp,
            delay:D_SWAP, codeLine:'4',
            msg:'Swap arr[' + i + '] \u2194 arr[' + (i+1) + ']',
            sub:'Larger value ' + arr[i+1] + ' bubbles one step to the right'
          });
        }
      }

      steps.push({
        arr: arr.slice(), lo:-1, hi:-1, sortedFrom:sortedFrom-1,
        swapping:false, pass:pass+1, cmp:cmp, swp:swp,
        delay:D_PASS_EN, codeLine:'1',
        msg:'Pass ' + (pass+1) + ' complete \u2014 ' + arr[sortedFrom-1] + ' is in its final position \u2713',
        sub:cmp + ' comparisons and ' + swp + ' swaps so far'
      });
    }

    steps.push({
      arr: arr.slice(), lo:-1, hi:-1, sortedFrom:0,
      swapping:false, pass:n-1, cmp:cmp, swp:swp,
      delay:D_DONE, codeLine:'5',
      msg:'\u2713 Fully sorted!  ' + cmp + ' comparisons,  ' + swp + ' swaps performed',
      sub:'O(n\u00b2) = O(' + n + '\u00b2) = O(' + (n*n) + ') operations worst case'
    });

    return steps;
  }

  var STEPS = computeSteps(VALUES);
  var idx     = 0;
  var playing = false;
  var timer   = null;
  var speed   = 1.0;

  // ── Element references ────────────────────────────────
  var barsG      = document.getElementById('barsG');
  var valsG      = document.getElementById('valsG');
  var idxsG      = document.getElementById('idxsG');
  var cmpG       = document.getElementById('cmpG');
  var descEl     = document.getElementById('descLabel');
  var subEl      = document.getElementById('descSub');
  var stepEl     = document.getElementById('stepLabel');
  var passEl     = document.getElementById('passLabel');
  var cmpEl      = document.getElementById('cmpLabel');
  var swpEl      = document.getElementById('swpLabel');
  var progEl     = document.getElementById('progressBar');
  var playBtnBg  = document.getElementById('playBtnBg');
  var playBtnTxt = document.getElementById('playBtnTxt');
  var arrowEl    = document.getElementById('codeArrow');
  var speedLbl   = document.getElementById('speedLbl');

  // Pseudocode line element map
  var CODE_KEYS = ['N1','1','2','3','4','5'];
  var codeTextMap = {};
  var codeHlMap   = {};
  // Y positions for the arrow indicator (matches text baseline y)
  var codeArrowY  = { 'N1':122, '1':140, '2':158, '3':176, '4':194, '5':212 };

  CODE_KEYS.forEach(function(k) {
    codeTextMap[k] = document.getElementById('cline' + k);
    codeHlMap[k]   = document.getElementById('chl'   + k);
  });

  // ── Create bar / label elements ───────────────────────
  var barEls = [], valEls = [], idxEls = [];
  for (var i = 0; i < N; i++) {
    var r = document.createElementNS(NS, 'rect');
    r.setAttribute('x', barX(i));
    r.setAttribute('width', BAR_W);
    r.setAttribute('rx', '5');
    barsG.appendChild(r);
    barEls.push(r);

    var vt = document.createElementNS(NS, 'text');
    vt.setAttribute('text-anchor', 'middle');
    vt.setAttribute('font-size', '17');
    vt.setAttribute('font-weight', '700');
    vt.setAttribute('fill', '#f0f6fc');
    valsG.appendChild(vt);
    valEls.push(vt);

    var it = document.createElementNS(NS, 'text');
    it.setAttribute('text-anchor', 'middle');
    it.setAttribute('font-size', '11');
    it.setAttribute('fill', '#484f58');
    it.textContent = '[' + i + ']';
    idxsG.appendChild(it);
    idxEls.push(it);
  }

  function clearGroup(g) {
    while (g.firstChild) g.removeChild(g.firstChild);
  }

  function svgEl(tag, attrs, text) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) {
      if (Object.prototype.hasOwnProperty.call(attrs, k))
        e.setAttribute(k, attrs[k]);
    }
    if (text !== undefined) e.textContent = text;
    return e;
  }

  // ── Render one step ───────────────────────────────────
  function render(si) {
    var s = STEPS[si];

    // Bars
    for (var i = 0; i < N; i++) {
      var h  = barH(s.arr[i]);
      var bx = barX(i);
      var cx = bx + BAR_W / 2;

      barEls[i].setAttribute('y',      BASE_Y - h);
      barEls[i].setAttribute('height', h);

      var color;
      if      (s.swapping  && (i === s.lo || i === s.hi)) color = C_SWAP;
      else if (!s.swapping && (i === s.lo || i === s.hi)) color = C_COMPARE;
      else if (i >= s.sortedFrom)                          color = C_SORTED;
      else                                                 color = C_NORMAL;
      barEls[i].setAttribute('fill', color);

      valEls[i].setAttribute('x', cx);
      valEls[i].setAttribute('y', BASE_Y - h - 9);
      valEls[i].textContent = s.arr[i];

      idxEls[i].setAttribute('x', cx);
      idxEls[i].setAttribute('y', BASE_Y + 18);
    }

    // Bracket
    clearGroup(cmpG);
    if (s.lo >= 0 && s.hi >= 0) {
      var loH  = barH(s.arr[s.lo]);
      var hiH  = barH(s.arr[s.hi]);
      var bx1  = barX(s.lo) - 5;
      var bx2  = barX(s.hi) + BAR_W + 5;
      var midX = (bx1 + bx2) / 2;
      var topY = BASE_Y - Math.max(loH, hiH) - 30;
      var clr  = s.swapping ? C_SWAP : C_COMPARE;
      var dash = s.swapping ? '0' : '5,3';

      cmpG.appendChild(svgEl('line',{x1:bx1,y1:topY+10,x2:bx2,y2:topY+10,
        stroke:clr,'stroke-width':'2','stroke-dasharray':dash}));
      cmpG.appendChild(svgEl('line',{x1:bx1,y1:topY+2,x2:bx1,y2:topY+18,
        stroke:clr,'stroke-width':'2'}));
      cmpG.appendChild(svgEl('line',{x1:bx2,y1:topY+2,x2:bx2,y2:topY+18,
        stroke:clr,'stroke-width':'2'}));
      cmpG.appendChild(svgEl('rect',{
        x:midX-42,y:topY-20,width:84,height:18,rx:'4',
        fill:clr,opacity:'0.2'}));
      cmpG.appendChild(svgEl('text',{
        x:midX,y:topY-6,'text-anchor':'middle',
        'font-size':'11','font-weight':'700',fill:clr,
        'font-family':"'Segoe UI',system-ui,Arial,sans-serif"},
        s.swapping ? 'SWAP' : 'COMPARE'));
      cmpG.setAttribute('opacity','1');
    } else {
      cmpG.setAttribute('opacity','0');
    }

    // Info panel
    stepEl.textContent = 'Step ' + (si + 1) + ' of ' + STEPS.length;
    descEl.textContent = s.msg;
    subEl.textContent  = s.sub || '';
    passEl.textContent = s.pass > 0 ? String(s.pass) : '\u2014';
    cmpEl.textContent  = String(s.cmp);
    swpEl.textContent  = String(s.swp);

    // Progress bar
    progEl.setAttribute('width', Math.round((si + 1) / STEPS.length * 860));

    // Pseudocode highlighting + arrow
    CODE_KEYS.forEach(function(k) {
      var active = (k === s.codeLine);
      if (codeTextMap[k]) {
        codeTextMap[k].setAttribute('fill', active ? '#fffbcc' : '#8b949e');
        codeTextMap[k].setAttribute('font-weight', active ? '700' : '400');
      }
      if (codeHlMap[k]) {
        codeHlMap[k].setAttribute('opacity', active ? '0.14' : '0');
      }
    });
    if (arrowEl && s.codeLine && codeArrowY[s.codeLine] !== undefined) {
      arrowEl.setAttribute('y', codeArrowY[s.codeLine]);
      arrowEl.setAttribute('opacity', '1');
    } else if (arrowEl) {
      arrowEl.setAttribute('opacity','0');
    }
  }

  // ── Animation driver ──────────────────────────────────
  function scheduleNext() {
    if (!playing) return;
    var delay = Math.max(80, Math.round(STEPS[idx].delay / speed));
    timer = setTimeout(function () {
      render(idx);
      idx = (idx + 1) % STEPS.length;
      scheduleNext();
    }, delay);
  }

  function startPlaying() {
    playing = true;
    playBtnTxt.textContent = '\u23F8 PAUSE';
    playBtnBg.setAttribute('fill','#21262d');
    clearTimeout(timer);
    scheduleNext();
  }

  function pausePlaying() {
    playing = false;
    playBtnTxt.textContent = '\u25B6 PLAY';
    playBtnBg.setAttribute('fill','#1f6feb');
    clearTimeout(timer);
  }

  // ── Buttons ───────────────────────────────────────────
  function addBtn(id, fn) {
    var el = document.getElementById(id);
    if (el) el.addEventListener('click', function(e) { e.stopPropagation(); fn(); });
  }

  addBtn('playBtn', function() { playing ? pausePlaying() : startPlaying(); });

  addBtn('stepBtn', function() {
    pausePlaying();
    render(idx);
    idx = (idx + 1) % STEPS.length;
  });

  addBtn('prevBtn', function() {
    pausePlaying();
    idx = (idx - 2 + STEPS.length) % STEPS.length;
    render(idx);
    idx = (idx + 1) % STEPS.length;
  });

  addBtn('resetBtn', function() {
    var was = playing;
    clearTimeout(timer);
    playing = false;
    idx = 0;
    render(idx);
    idx = 1;
    if (was) startPlaying();
  });

  // Button hover effects
  function hoverBtn(bgId, hoverColor, defaultColor) {
    var bg = document.getElementById(bgId);
    var btn = document.getElementById(bgId.replace('Bg',''));
    if (!btn || !bg) return;
    btn.addEventListener('mouseover', function() { bg.setAttribute('fill', hoverColor); });
    btn.addEventListener('mouseout',  function() { bg.setAttribute('fill', defaultColor); });
  }
  hoverBtn('stepBtnBg',  '#2d333b', '#21262d');
  hoverBtn('prevBtnBg',  '#2d333b', '#21262d');
  hoverBtn('resetBtnBg', '#2d333b', '#21262d');

  // ── Speed slider ──────────────────────────────────────
  var SLIDER_X  = 430;
  var SLIDER_W  = 190;
  var SL_MIN    = 0.3;
  var SL_MAX    = 3.0;
  var sliderThumb = document.getElementById('sliderThumb');
  var sliderFill  = document.getElementById('sliderFill');
  var dragging    = false;

  function speedFromX(x) {
    var pct = Math.max(0, Math.min(1, (x - SLIDER_X) / SLIDER_W));
    return Math.round((SL_MIN + pct * (SL_MAX - SL_MIN)) * 10) / 10;
  }
  function xFromSpeed(sp) {
    return SLIDER_X + ((sp - SL_MIN) / (SL_MAX - SL_MIN)) * SLIDER_W;
  }
  function setSpeed(newSpeed) {
    speed = Math.max(SL_MIN, Math.min(SL_MAX, newSpeed));
    var tx = xFromSpeed(speed);
    sliderThumb.setAttribute('cx', tx);
    sliderFill.setAttribute('width', tx - SLIDER_X);
    speedLbl.textContent = speed.toFixed(1) + 'x';
  }
  function svgXFromEvent(e) {
    var pt = document.documentElement.createSVGPoint();
    pt.x = e.clientX; pt.y = e.clientY;
    return pt.matrixTransform(document.documentElement.getScreenCTM().inverse()).x;
  }

  var sliderArea = document.getElementById('sliderArea');
  sliderArea.addEventListener('mousedown', function(e) {
    e.stopPropagation();
    dragging = true;
    setSpeed(speedFromX(svgXFromEvent(e)));
  });
  document.documentElement.addEventListener('mousemove', function(e) {
    if (!dragging) return;
    setSpeed(speedFromX(svgXFromEvent(e)));
  });
  document.documentElement.addEventListener('mouseup',   function() { dragging = false; });

  // ── Init ──────────────────────────────────────────────
  setSpeed(1.0);
  render(0);
  idx = 1;
  startPlaying();

}());
